def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_bids = []
    rich_threat_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    threat_bids.append(float(bid))
                if opp.get('budget', 0) >= DAILY_SALARY * 2:
                    rich_threat_bids.append(float(bid))

    if not alive:
        return float(min(budget, 10.0))

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    base = DAILY_SALARY * 0.52
    if loose_supply:
        base = DAILY_SALARY * 0.38
    elif tight_supply:
        base = DAILY_SALARY * 0.72

    if no_water_days >= 2 or hp <= 3:
        urgent = DAILY_SALARY * 1.28 if tight_supply else DAILY_SALARY * 1.05
        if rich_threat_bids:
            urgent = max(urgent, max(rich_threat_bids) + 2.0)
        elif threat_bids:
            urgent = max(urgent, max(threat_bids) + 1.5)
        return float(max(0.0, min(budget, urgent)))

    if hp <= 5 or no_water_days == 1:
        defend = DAILY_SALARY * 0.88 if tight_supply else DAILY_SALARY * 0.72
        if threat_bids:
            defend = max(defend, min(max(threat_bids) + 1.0, DAILY_SALARY * 1.15))
        return float(max(0.0, min(budget, defend)))

    target = base
    if rich_threat_bids:
        strongest = max(rich_threat_bids)
        if strongest >= DAILY_SALARY * 1.8:
            target = DAILY_SALARY * 0.42 if not tight_supply else DAILY_SALARY * 0.82
        elif strongest >= DAILY_SALARY * 1.15:
            target = max(target, DAILY_SALARY * 0.76)
        else:
            target = max(target, strongest + 1.0)
    elif threat_bids:
        strongest = max(threat_bids)
        target = max(target, strongest + 1.0)

    if day >= 8 and hp >= 7 and no_water_days == 0:
        target *= 0.9

    reserve_floor = DAILY_SALARY * max(0, 10 - day)
    if budget < reserve_floor and hp >= 6 and no_water_days == 0:
        target = min(target, DAILY_SALARY * 0.5)

    target = max(0.0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and extract yesterday bids
    alive_opps = []
    yesterday_bids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)
            prev = o.get('previous_trace', {}) or {}
            if prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    # If no alive opponents, spend to maximize remaining HP
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Use yesterday behavior pressure: target slightly above the top survivor bid
    # (Bob/Cindy died; their bids likely not useful for ongoing pressure.)
    top_bid = 0.0
    if yesterday_bids:
        top_bid = max(yesterday_bids)

    # Compute how many water units are likely available/needed
    # (index-safe: no lists used)
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Urgency factor
    urgency = 0.0
    if my_hp <= 2.0:
        urgency = 1.0
    elif my_hp <= 4.0:
        urgency = 0.6
    else:
        urgency = 0.25

    # Supply factor: higher supply -> bid less aggressively
    # supply in [15,25]
    if supply >= 22.0:
        supply_factor = 0.75
    elif supply >= 18.0:
        supply_factor = 1.0
    else:
        supply_factor = 1.15

    # If we have been without water, increase bid
    if no_water_days >= 2:
        urgency = min(1.0, urgency + 0.25)

    # Base strategy: match/beat top_bid when it's around survivor range.
    # Eric/Alex were averaging ~133-150; we target slightly above that when supply is not high.
    target = top_bid
    if top_bid < DAILY_SALARY * 0.6:
        # If yesterday bids were low overall, still bid enough to secure water.
        target = DAILY_SALARY * 0.6
    else:
        # Beat the leader by a margin scaled by urgency/supply.
        target = top_bid + (8.0 * urgency) + (2.0 * (1.0 - supply_factor))

    # Convert target into a spend cap based on remaining budget
    # Also avoid spending too much when budget is low.
    spend_cap = my_budget

    # Ensure we don't exceed what we can afford
    bid = min(spend_cap, target * supply_factor)

    # If budget is very low, bid conservatively but try to secure at least some chance
    if my_budget <= DAILY_SALARY * 0.25:
        bid = min(my_budget, DAILY_SALARY * (0.35 + 0.5 * urgency))

    # Hard bounds
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    else:
        yesterday_bids = []
        for opp in alive_opponents:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.85:
                if my_status['hp'] > 3:
                    base_bid = DAILY_SALARY * 0.3
                else:
                    base_bid = DAILY_SALARY * 0.95
            else:
                base_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
        else:
            base_bid = DAILY_SALARY * 0.5

    num_water_slots = int(day_context['supply'] // WATER_REQ)
    total_competitors_for_slots = num_alive_opponents + 1

    if num_water_slots < total_competitors_for_slots:
        if my_status['hp'] <= 4:
            base_bid *= 1.2
            base_bid = min(base_bid, DAILY_SALARY * 1.0)
        else:
            base_bid *= 1.1
            base_bid = min(base_bid, DAILY_SALARY * 0.9)
    elif num_water_slots > total_competitors_for_slots:
        if my_status['hp'] > 4:
            base_bid *= 0.8
            base_bid = max(base_bid, DAILY_SALARY * 0.2)
        else:
            base_bid *= 0.9
            base_bid = max(base_bid, DAILY_SALARY * 0.3)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 4:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)
        elif my_status['budget'] > DAILY_SALARY * 1.5:
            base_bid = max(base_bid, DAILY_SALARY * 0.85)

    final_bid = max(0.0, min(base_bid, my_status['budget']))

    if final_bid == 0 and my_status['budget'] > 0:
        if my_status['hp'] <= 2:
             final_bid = min(my_status['budget'], DAILY_SALARY * 0.5)
        else:
            final_bid = min(my_status['budget'], 1.0)

    return final_bid
